    const patterns = {};

    for (const failure of allFailures) {
      if (!patterns[failure.fingerprint]) {
        patterns[failure.fingerprint] = {
          ...failure,
          count: 0,
          recent: []
        };
      }
      patterns[failure.fingerprint].count++;
      patterns[failure.fingerprint].recent.push(failure.timestamp);
    }

