    const marketplace = new this.mp();
    const posted = [];

    for (const pattern of patterns) {
      if (pattern.count >= 3) {
        try {
          const result = marketplace.postProblem({
            title: `Pattern: ${pattern.model} ${pattern.status} (${pattern.count}x)`,
            description: `Detected ${pattern.count} failures in 72h: ${pattern.summary}. Failed actions: ${pattern.failedActions}. Fingerprint: ${pattern.fingerprint}`,
            domain: 'system-reliability',
            difficulty: pattern.count > 5 ? 'critical' : 'high',
            postedBy: 'city-col-propagate'
          });

          posted.push({
            patternId: pattern.fingerprint,
            problemId: result.id,
            count: pattern.count,
            timestamp: new Date().toISOString()
          });
        } catch (e) {
          console.error(`Failed to post pattern ${pattern.fingerprint}: ${e.message}`);
        }
      }
    }

    return posted;
  }

  snapshot() {
    const patterns = this.detectPatterns();
    const totalFailures = patterns.reduce((sum, p) => sum + p.count, 0);

    return {
      timestamp: new Date().toISOString(),
      totalPatterns: patterns.length,
      totalFailures,
      topPatterns: patterns.slice(0, 5).map(p => ({
        fingerprint: p.fingerprint.substring(0, 8),
        model: p.model,
        status: p.status,
        count: p.count,
        summary: p.summary
      })),
      needsPropagation: patterns.filter(p => p.count >= 3).length
    };
  }
